R=Path(__file__).parent; D=R/'dist'; D.mkdir(exist_ok=True)
nav=[('','Trang chủ'),('gioi-thieu','Tổng quan'),('khuon-vien-mo','Khuôn viên mộ'),('gia-dat-nghia-trang-lac-hong-vien','Bảng giá'),('vi-tri','Vị trí'),('dich-vu','Dịch vụ'),('thu-vien','Thư viện'),('cam-nang','Cẩm nang'),('lien-he','Liên hệ')]
def url(s):return '/'+s+'/' if s else '/'
def img(n,alt,cls=''):return f'<img class="{cls}" src="/assets/{n}.jpg" alt="{alt}" loading="lazy" width="1200" height="800">'
def link(s,t,cl='text-link'):return f'<a class="{cl}" href="{url(s)}">{t} <span aria-hidden="true">↗</span></a>'
def head(k,title,desc):return f'<section class="page-head wrap"><p class="eyebrow">LẠC HỒNG VIÊN / {k}</p><h1>{title}</h1><p class="lead">{desc}</p></section>'
def cta():return '<section class="cta wrap"><div><p class="eyebrow">CÙNG GIA ĐÌNH CHUẨN BỊ CHU ĐÁO</p><h2>Một cuộc trao đổi.<br>Thêm nhiều điều an tâm.</h2><p>Trao đổi nhu cầu, hỏi rõ chi phí và hẹn ngày khảo sát thực tế.</p></div><a class="button cream" href="/lien-he/">Trao đổi với tư vấn viên ↗</a></section>'
def cards():
 return ''.join(f'<a class="property" data-type="{tag}" href="/khuon-vien-mo/#{slug}">{img(photo,title)}<div><span class="eyebrow">{no} / {tag}</span><h3>{title}</h3><p>{desc}</p><span class="text-link">Tìm hiểu phương án ↗</span></div></a>' for no,tag,slug,photo,title,desc in [('01','Cá nhân','mo-don','memorial','Mộ đơn','Không gian tưởng niệm dành cho một người thân.'),('02','Đôi','mo-doi','couple','Mộ đôi','Sự gắn bó được gìn giữ trong cùng một khuôn viên.'),('03','Gia đình','gia-dinh','family','Khuôn viên gia đình','Chủ động sắp xếp nơi an nghỉ cho nhiều thế hệ.')])
faq=[('Giá đất Lạc Hồng Viên được tính như thế nào?','Cần đối chiếu báo giá theo đúng mã lô, diện tích và hạng mục đi kèm. Hãy hỏi riêng chi phí khuôn viên, xây dựng, thuế và chăm sóc trước khi so sánh.'),('Nên chọn mộ đơn, mộ đôi hay khuôn viên gia đình?','Bắt đầu từ số vị trí an táng cần bố trí, nhu cầu của gia đình và ngân sách tổng thể. Sau đó khảo sát thực tế để lựa chọn phương án phù hợp.'),('Có thể đặt lịch tham quan trước không?','Bạn có thể gọi 0971 999 470 để trao đổi thời gian và điểm hẹn. Lịch tham quan cần được tư vấn viên xác nhận trực tiếp.'),('Cần chuẩn bị gì trước khi tìm hiểu?','Ghi lại nhu cầu an táng, số vị trí dự kiến, ngân sách, thời gian cần sử dụng và các câu hỏi về hợp đồng, quản lý, chăm sóc.')]
def faqs():return '<div class="faqs">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faq)+'</div>'
P={}
P['']=('Lạc Hồng Viên – Kênh thông tin dự án & tư vấn khuôn viên mộ','Tìm hiểu Công viên Nghĩa trang Lạc Hồng Viên: tổng quan, khuôn viên mộ, thông tin giá, dịch vụ và lịch tham quan.', '''<section class="hero"><img src="/assets/landscape.jpg" alt="Cảnh quan Công viên Nghĩa trang Lạc Hồng Viên" width="1600" height="1000" fetchpriority="high"><div class="hero-shade"></div><div class="wrap hero-content"><p class="eyebrow">CÔNG VIÊN NGHĨA TRANG LẠC HỒNG VIÊN</p><h1>Nơi an nghỉ bình yên.<br>Nơi tình thân còn mãi.</h1><p>Một không gian xanh để tưởng nhớ người thân.<br>Một sự chuẩn bị chu đáo cho những điều dài lâu.</p><div class="actions"><a class="button cream" href="/khuon-vien-mo/">Khám phá khuôn viên ↗</a><a class="hero-link" href="/lien-he/">Hẹn lịch tham quan →</a></div><div class="hero-foot"><span>THIÊN NHIÊN · TƯỞNG NIỆM · KẾT NỐI</span><span>Khám phá bên dưới ↓</span></div></div></section><section class="intro wrap"><p class="eyebrow">KHÔNG GIAN CỦA SỰ AN YÊN</p><div><h2>Gìn giữ ký ức.<br>Vun đắp sự an lòng.</h2><p>Lựa chọn nơi an nghỉ cho người thân là một quyết định cần thời gian và sự thấu hiểu. Kênh thông tin Lạc Hồng Viên giúp gia đình tìm hiểu từng phương án, chuẩn bị câu hỏi và kết nối tư vấn trước khi khảo sát.</p>'''+link('gioi-thieu','Tìm hiểu về dự án')+'''</div></section><section class="wrap section"><div class="section-top"><div><p class="eyebrow">LỰA CHỌN PHÙ HỢP VỚI GIA ĐÌNH</p><h2>Mỗi gia đình, một sự chuẩn bị.</h2></div>'''+link('khuon-vien-mo','Xem các loại khuôn viên')+'''</div><div class="properties">'''+cards()+'''</div></section><section class="image-split"><div>'''+img('garden','Cảnh quan khuôn viên Lạc Hồng Viên')+'''</div><div class="split-copy"><p class="eyebrow">TÌM HIỂU TRƯỚC KHI LỰA CHỌN</p><h2>An tâm bắt đầu<br>từ thông tin rõ ràng.</h2><p>Chúng tôi tập hợp những điều gia đình thường quan tâm: vị trí, phương án khuôn viên, các khoản chi phí và chăm sóc sau an táng.</p><a href="/gia-dat-nghia-trang-lac-hong-vien/" class="line-item">01 <span>Thông tin giá & cấu phần chi phí</span> ↗</a><a href="/vi-tri/" class="line-item">02 <span>Vị trí & chuẩn bị chuyến đi</span> ↗</a><a href="/dich-vu/" class="line-item">03 <span>Dịch vụ & chăm sóc phần mộ</span> ↗</a></div></section><section class="wrap section"><p class="eyebrow">NHỮNG ĐIỀU GIA ĐÌNH THƯỜNG HỎI</p><h2>Hiểu rõ hơn, nhẹ lòng hơn.</h2>'''+faqs()+'''</section>'''+cta())
P['gioi-thieu']=('Tổng quan Lạc Hồng Viên | Không gian & cách tìm hiểu dự án','Tổng quan không gian Lạc Hồng Viên và các bước tìm hiểu dự án trước khi gia đình lựa chọn khuôn viên mộ.',head('TỔNG QUAN','Một không gian tưởng niệm,<br>một sự gắn kết dài lâu.','Tìm hiểu dự án từ cảnh quan, nhu cầu của gia đình đến những điều cần xác nhận khi khảo sát.')+f'<div class="wrap panoramic">{img("landscape","Toàn cảnh xanh tại Lạc Hồng Viên")}</div>'+'''<section class="wrap editorial section"><aside><span class="eyebrow">01 / TINH THẦN KHÔNG GIAN</span><h2>Để mỗi lần trở về<br>là một lần gần nhau.</h2></aside><div><p class="large-copy">Nơi tưởng niệm không chỉ là điểm đến trong ngày giỗ, Tết hay tiết Thanh Minh. Đó còn là nơi con cháu gìn giữ câu chuyện của gia đình.</p><p>Lạc Hồng Viên được giới thiệu theo mô hình công viên nghĩa trang, kết hợp không gian phần mộ với cảnh quan và dịch vụ liên quan. Khi tìm hiểu, gia đình nên cân nhắc đồng thời sự thuận tiện đi lại, cách bố trí khuôn viên và khả năng chăm sóc lâu dài.</p><p>Website congviennghiatrang.com là kênh thông tin và kết nối tư vấn về dự án. Thông tin về từng lô, điều kiện sử dụng và dịch vụ cần được đối chiếu với hồ sơ, báo giá và hợp đồng thực tế.</p></div></section><section class="soft"><div class="wrap section"><p class="eyebrow">LỘ TRÌNH TÌM HIỂU</p><h2>Từng bước chuẩn bị cùng gia đình.</h2><div class="steps">'''+''.join(f'<article><span>0{i}</span><h3>{t}</h3><p>{d}</p></article>' for i,t,d in [(1,'Làm rõ nhu cầu','Trao đổi số vị trí an táng, ngân sách và thời gian dự kiến sử dụng.'),(2,'Khảo sát thực tế','Quan sát cảnh quan, lối đi, vị trí và điều kiện tiếp cận khuôn viên.'),(3,'Đối chiếu thông tin','Kiểm tra mã lô, diện tích, các khoản chi phí và điều kiện trong hợp đồng.'),(4,'Thống nhất phương án','Gia đình cùng trao đổi và xác nhận trước khi đưa ra quyết định.')])+'''</div></div></section>'''+cta())
P['khuon-vien-mo']=('Khuôn viên mộ Lạc Hồng Viên | Mộ đơn, mộ đôi & gia đình','So sánh nhu cầu mộ đơn, mộ đôi và khuôn viên gia đình tại Lạc Hồng Viên; chuẩn bị lựa chọn trước khi khảo sát.',head('KHUÔN VIÊN MỘ','Một nơi an nghỉ.<br>Nhiều cách gìn giữ tình thân.','Lựa chọn từ nhu cầu thực tế của gia đình, sau đó đối chiếu vị trí, diện tích và phương án bố trí.')+'''<section class="wrap"><div class="filter-bar" role="group" aria-label="Lọc loại khuôn viên"><button class="chip active" data-filter="all" aria-pressed="true">Tất cả</button><button class="chip" data-filter="Cá nhân" aria-pressed="false">Mộ đơn</button><button class="chip" data-filter="Đôi" aria-pressed="false">Mộ đôi</button><button class="chip" data-filter="Gia đình" aria-pressed="false">Gia đình</button></div><div class="properties">'''+cards()+'''</div></section><section class="wrap section"><p class="eyebrow">SO SÁNH THEO NHU CẦU</p><h2>Phương án nào phù hợp?</h2><div class="table-scroll"><table><caption>So sánh loại hình khuôn viên trước khi khảo sát</caption><thead><tr><th>Tiêu chí</th><th>Mộ đơn</th><th>Mộ đôi</th><th>Khuôn viên gia đình</th></tr></thead><tbody><tr><th>Nhu cầu chính</th><td>Một người thân</td><td>Hai người thân</td><td>Nhiều thành viên</td></tr><tr><th>Ưu tiên tìm hiểu</th><td>Vị trí & lối đi</td><td>Bố trí hai phần mộ</td><td>Quy hoạch tổng thể</td></tr><tr><th>Cần xác nhận</th><td>Diện tích từng lô</td><td>Khoảng cách & thiết kế</td><td>Số vị trí được phép bố trí</td></tr><tr><th>Chi phí</th><td colspan="3">Báo giá theo lô và phạm vi hạng mục thực tế; không suy ra tổng giá chỉ từ số phần mộ.</td></tr></tbody></table></div></section>'''+''.join(f'<section class="wrap option-detail" id="{slug}"><span class="number">{i}</span><div><h2>{t}</h2><p>{d}</p>{link("lien-he","Trao đổi nhu cầu")}</div></section>' for i,slug,t,d in [('01','mo-don','Mộ đơn','Phù hợp khi gia đình cần chuẩn bị một vị trí an nghỉ. Khi đi xem, hãy kiểm tra vị trí, độ thuận tiện khi thăm viếng và các hạng mục xây dựng được phép thực hiện.'),('02','mo-doi','Mộ đôi','Dành cho nhu cầu bố trí hai người thân cạnh nhau. Cần trao đổi rõ kích thước, cách xây dựng và phương án sử dụng từng vị trí.'),('03','gia-dinh','Khuôn viên gia đình','Giúp gia đình chủ động trao đổi phương án an nghỉ cho nhiều thành viên. Cần xác nhận số vị trí, lối đi, công trình chung và trách nhiệm quản lý trong hợp đồng.')])+cta())
P['gia-dat-nghia-trang-lac-hong-vien']=('Giá đất nghĩa trang Lạc Hồng Viên | Hướng dẫn nhận bảng giá','Tìm hiểu giá đất Lạc Hồng Viên theo loại mộ và cấu phần chi phí. Nhận báo giá theo mã lô, diện tích, xây dựng và dịch vụ.',head('THÔNG TIN CHI PHÍ','Giá đất Lạc Hồng Viên.<br>Hiểu đủ trước khi so sánh.','Giá cần gắn với một vị trí cụ thể và danh mục hạng mục rõ ràng. Gia đình nên yêu cầu báo giá bằng văn bản trước khi quyết định.')+'''<section class="wrap pricing-layout"><div><div class="notice"><strong>Thông tin bảng giá</strong><p>Website chưa công bố mức giá xác nhận cho từng lô. Vui lòng liên hệ để kiểm tra quỹ lô và nhận báo giá tại thời điểm tư vấn.</p></div><h2>Bảng yêu cầu báo giá theo loại hình</h2><div class="table-scroll"><table><caption>Các thông tin cần có trong báo giá Lạc Hồng Viên</caption><thead><tr><th>Loại hình</th><th>Cần xác định</th><th>Báo giá</th></tr></thead><tbody><tr><th>Mộ đơn</th><td>Mã lô, diện tích, vị trí</td><td>Liên hệ theo lô</td></tr><tr><th>Mộ đôi</th><td>Bố trí hai phần mộ, xây dựng</td><td>Liên hệ theo lô</td></tr><tr><th>Gia đình / gia tộc</th><td>Diện tích, số vị trí, cảnh quan</td><td>Liên hệ theo phương án</td></tr></tbody></table></div><h2 class="mt">Những khoản cần hỏi rõ</h2><div class="cost-list">'''+''.join(f'<article><span>0{i}</span><div><h3>{t}</h3><p>{d}</p></div></article>' for i,t,d in [(1,'Chi phí khuôn viên','Giá gắn với mã lô, diện tích và phạm vi quyền, nghĩa vụ ghi trong hợp đồng.'),(2,'Thiết kế và xây dựng','Làm rõ những gì đã bao gồm: phần mộ, bia, lối đi, tiểu cảnh và hạng mục chung.'),(3,'Thuế và các khoản khác','Hỏi giá đã bao gồm thuế hay chưa, thời điểm thanh toán và các khoản có thể phát sinh.'),(4,'Quản lý và chăm sóc','Xác nhận phạm vi dịch vụ, thời hạn, tần suất thực hiện và cách điều chỉnh phí.')])+'''</div></div><aside class="quote-box"><p class="eyebrow">CHUẨN BỊ ĐỂ NHẬN BÁO GIÁ</p><h2>Một yêu cầu<br>rõ ràng hơn.</h2><ul><li>Loại khuôn viên cần tìm</li><li>Số vị trí an táng dự kiến</li><li>Khoảng ngân sách tổng thể</li><li>Thời điểm cần sử dụng</li></ul><a class="button cream" href="/lien-he/?nhucau=bao-gia">Yêu cầu tư vấn giá ↗</a><p>Hotline <a href="tel:0971999470">0971 999 470</a></p></aside></section><section class="wrap section"><h2>Câu hỏi về giá đất Lạc Hồng Viên</h2>'''+faqs()+'''<p>Để tìm hiểu cảnh quan và mô hình dự án, xem '''+link('','tổng quan Lạc Hồng Viên')+'''.</p></section>''')
P['vi-tri']=('Vị trí Lạc Hồng Viên | Chỉ đường & chuẩn bị tham quan','Xem chỉ đường Lạc Hồng Viên, chuẩn bị hành trình khảo sát và những điều cần xác nhận trước khi khởi hành.',head('VỊ TRÍ & HÀNH TRÌNH','Dành một chuyến đi,<br>để hiểu rõ hơn nơi trở về.','Quan sát trực tiếp cảnh quan, đường đi và vị trí khuôn viên giúp gia đình có thêm cơ sở trước khi lựa chọn.')+'''<section class="wrap location-grid"><div class="map-panel"><div class="map-marker">⌖</div><p class="eyebrow">ĐIỂM ĐẾN</p><h2>Lạc Hồng Viên</h2><p>Tra cứu vị trí và tuyến đi trên bản đồ</p><a class="button" href="https://www.google.com/maps/search/?api=1&query=Lac+Hong+Vien" target="_blank" rel="noopener">Mở Google Maps ↗</a><small>Xác nhận điểm đón và cổng vào với tư vấn viên trước khi đi.</small></div><div><p class="eyebrow">CHUẨN BỊ CHUYẾN THAM QUAN</p><h2>Một lịch trình<br>vừa đủ thảnh thơi.</h2><ol class="visit-list"><li><h3>Trước khi khởi hành</h3><p>Gọi xác nhận lịch hẹn, địa điểm gặp, người hướng dẫn và điều kiện đường đi trong ngày.</p></li><li><h3>Khi khảo sát</h3><p>Xem vị trí thực tế, lối tiếp cận, cảnh quan và khoảng cách tới các khu vực dịch vụ.</p></li><li><h3>Sau chuyến đi</h3><p>Tổng hợp thông tin, yêu cầu báo giá theo lô và dành thời gian trao đổi cùng gia đình.</p></li></ol></div></section><div class="wrap panoramic">'''+img('garden','Không gian cảnh quan để gia đình khảo sát tại Lạc Hồng Viên')+'''</div>'''+cta())
services=[('01','Chăm sóc phần mộ','Trao đổi kế hoạch vệ sinh, chăm sóc cây xanh và kiểm tra hiện trạng. Gia đình cần xác nhận tần suất, phạm vi công việc và cách nhận thông tin sau mỗi lần thực hiện.'),('02','Hỗ trợ an táng','Trao đổi các đầu việc cần phối hợp trước, trong và sau lễ an táng. Yêu cầu đơn vị tư vấn xác nhận lịch, quy trình và trách nhiệm của từng bên.'),('03','Thiết kế khuôn viên','Làm rõ phương án bố trí phần mộ, lối đi và hạng mục chung. Mọi bản thiết kế cần được đối chiếu với quy định áp dụng cho vị trí cụ thể.'),('04','Hỗ trợ thăm viếng','Hỏi trước về thời gian tiếp đón, điểm dừng nghỉ và dịch vụ phục vụ gia đình. Phạm vi cung cấp cần được xác nhận khi đặt lịch.')]
P['dich-vu']=('Dịch vụ tại Lạc Hồng Viên | Chăm sóc & hỗ trợ gia đình','Tìm hiểu các nhóm dịch vụ chăm sóc phần mộ, hỗ trợ an táng, thiết kế khuôn viên và thăm viếng tại Lạc Hồng Viên.',head('DỊCH VỤ','Sự chu đáo tiếp nối,<br>qua từng lần chăm sóc.','Tìm hiểu phạm vi hỗ trợ và yêu cầu xác nhận bằng văn bản những dịch vụ gia đình cần sử dụng.')+'''<section class="wrap service-feature">'''+img('temple','Cảnh quan và không gian thăm viếng Lạc Hồng Viên')+'''<blockquote>“Chuẩn bị kỹ từng việc nhỏ,<br>để gia đình có thêm thời gian<br>dành cho những điều ý nghĩa.”</blockquote></section><section class="wrap section services">'''+''.join(f'<article><span class="number">{i}</span><h2>{t}</h2><p>{d}</p>{link("lien-he","Hỏi về dịch vụ")}</article>' for i,t,d in services)+'''</section><section class="soft"><div class="wrap section"><p class="eyebrow">TRƯỚC KHI ĐĂNG KÝ</p><h2>Hỏi rõ phạm vi. Thống nhất chi phí.</h2><p class="lead">Gia đình nên lưu danh mục công việc, thời gian thực hiện, chi phí, đầu mối liên hệ và cách xử lý khi có thay đổi. Các nhóm dịch vụ trên là nội dung cần trao đổi, không thay thế cam kết cung cấp trong hợp đồng.</p></div></section>'''+cta())
photos=[('landscape','Toàn cảnh','Cảnh quan Công viên Nghĩa trang Lạc Hồng Viên'),('garden','Cảnh quan','Không gian khuôn viên và cây xanh'),('family','Khuôn viên','Khuôn viên phần mộ gia đình'),('temple','Cảnh quan','Không gian thăm viếng'),('memorial','Khuôn viên','Chi tiết không gian tưởng niệm'),('couple','Khuôn viên','Phương án bố trí phần mộ')]
P['thu-vien']=('Thư viện ảnh Lạc Hồng Viên | Cảnh quan & khuôn viên','Xem ảnh cảnh quan và khuôn viên Lạc Hồng Viên, mở ảnh lớn để tìm hiểu không gian trước khi đi khảo sát.',head('THƯ VIỆN HÌNH ẢNH','Một góc nhìn gần hơn<br>về không gian bình yên.','Ảnh từ website congviennghiatrang.com. Hiện trạng từng khu vực cần được kiểm tra trong chuyến khảo sát thực tế.')+'''<section class="wrap section gallery">'''+''.join(f'<button class="photo" data-photo="/assets/{n}.jpg" data-caption="{a}" aria-label="Xem ảnh lớn: {a}">{img(n,a)}<span>{cat} <b>↗</b></span></button>' for n,cat,a in photos)+'''</section><dialog id="lightbox"><button class="close" aria-label="Đóng ảnh">×</button><img src="/assets/landscape.jpg" alt=""><p></p></dialog>'''+cta())
articles=[('kinh-nghiem-chon-khuon-vien','LỰA CHỌN KHUÔN VIÊN','5 điều nên hỏi trước khi chọn khuôn viên mộ','Từ nhu cầu của gia đình đến chi phí và chăm sóc: một danh sách để bạn bắt đầu.','family',[('1. Gia đình cần chuẩn bị cho bao nhiêu người?','Làm rõ nhu cầu hiện tại và dự kiến trong tương lai. Việc trao đổi sớm giúp gia đình cân nhắc mộ đơn, mộ đôi hoặc một khuôn viên chung phù hợp.'),('2. Vị trí có thuận tiện thăm viếng?','Quan sát đường đi, chỗ dừng chân, lối tiếp cận và điều kiện di chuyển của người lớn tuổi. Không nên chỉ quyết định qua ảnh.'),('3. Báo giá gồm những hạng mục nào?','Yêu cầu báo giá có mã lô, diện tích và danh mục chi tiết. So sánh tổng chi phí thay vì chỉ nhìn đơn giá trên mét vuông.'),('4. Các cam kết được ghi ở đâu?','Đối chiếu thông tin tư vấn với hồ sơ và hợp đồng. Hỏi rõ bên ký, phạm vi sử dụng, nghĩa vụ và đầu mối xử lý khi cần hỗ trợ.'),('5. Chăm sóc lâu dài ra sao?','Làm rõ tần suất, phạm vi, chi phí và cách nhận cập nhật hiện trạng. Giữ lại các thỏa thuận để gia đình tiện theo dõi.')]),('chuan-bi-tham-quan','HÀNH TRÌNH THAM QUAN','Chuẩn bị gì cho một chuyến khảo sát Lạc Hồng Viên?','Một chuyến đi có mục tiêu rõ ràng giúp gia đình tiết kiệm thời gian và thu nhận đủ thông tin.','landscape',[('Hẹn trước và thống nhất nhu cầu','Trao đổi số người đi, ngày dự kiến, điểm gặp và loại khuôn viên muốn xem. Chỉ khởi hành sau khi được xác nhận lịch trực tiếp.'),('Mang theo danh sách câu hỏi','Ghi các câu hỏi về vị trí, diện tích, phạm vi bố trí, chi phí và chăm sóc. Có thể chuẩn bị một bảng ghi chú để so sánh các lựa chọn.'),('Quan sát ngoài phần mộ','Dành thời gian xem đường tiếp cận, cảnh quan và khoảng cách di chuyển. Cân nhắc trải nghiệm thăm viếng của cả người cao tuổi trong gia đình.'),('Lưu thông tin sau khảo sát','Xin mã lô, phương án minh họa và báo giá bằng văn bản. Cùng gia đình xem lại thông tin trước khi thống nhất lựa chọn.')]),('cach-doc-bao-gia','CHI PHÍ & CHUẨN BỊ','Cách đọc một báo giá khuôn viên mộ đầy đủ','Đọc cùng một phạm vi hạng mục để việc so sánh giữa các phương án có ý nghĩa.','garden',[('Bắt đầu từ đúng vị trí','Một báo giá nên gắn với mã lô và diện tích cụ thể. Ảnh minh họa chung không thay thế thông tin nhận diện vị trí được chào bán.'),('Tách từng nhóm chi phí','Phân biệt chi phí khuôn viên, thiết kế, xây dựng, quản lý, chăm sóc và thuế. Hỏi những hạng mục chưa có trong báo giá để tránh bỏ sót.'),('Kiểm tra thời điểm áp dụng','Xác nhận thời hạn báo giá, tình trạng quỹ lô và tiến độ thanh toán. Chỉ ghi nhận ưu đãi khi có điều kiện áp dụng rõ ràng bằng văn bản.'),('Lưu báo giá cùng hồ sơ','Giữ bản báo giá, phương án và nội dung đã xác nhận. Khi có thay đổi, yêu cầu cập nhật để tất cả các bên cùng hiểu một thông tin.')])]
P['cam-nang']=('Cẩm nang Lạc Hồng Viên | Kinh nghiệm lựa chọn & tham quan','Cẩm nang chuẩn bị tham quan, lựa chọn khuôn viên mộ và đọc báo giá; thông tin thiết thực cho gia đình tìm hiểu Lạc Hồng Viên.',head('CẨM NANG GIA ĐÌNH','Đọc để hiểu.<br>Chuẩn bị để an tâm.','Những hướng dẫn ngắn gọn, giúp gia đình bắt đầu từ câu hỏi đúng và thông tin cần thiết.')+'''<section class="wrap section"><label class="search-label" for="article-search">Tìm bài trong cẩm nang</label><input id="article-search" type="search" placeholder="Tìm theo chủ đề, ví dụ: báo giá…"><div class="article-grid">'''+''.join(f'<article class="article-card" data-search="{t.lower()} {d.lower()}"><a href="/{slug}/">{img(photo,t)}<p class="eyebrow">{cat}</p><h2>{t}</h2><p>{d}</p><span class="text-link">Đọc hướng dẫn ↗</span></a></article>' for slug,cat,t,d,photo,body in articles)+'''</div><p id="no-results" hidden>Chưa có bài phù hợp. Thử tìm “khuôn viên”, “khảo sát” hoặc “báo giá”.</p></section>'''+cta())
for slug,cat,t,d,photo,body in articles:
 P[slug]=(t+' | Cẩm nang Lạc Hồng Viên',d,head(cat,t,d)+f'<div class="wrap article-cover">{img(photo,t)}</div><section class="wrap article-layout"><aside><p class="eyebrow">TRONG BÀI VIẾT</p>'+''.join(f'<a href="#muc-{i}">{h}</a>' for i,(h,b) in enumerate(body))+'</aside><article class="article-body"><p class="article-meta">Ban biên tập congviennghiatrang.com · Hướng dẫn tham khảo</p>'+''.join(f'<section id="muc-{i}"><h2>{h}</h2><p>{b}</p></section>' for i,(h,b) in enumerate(body))+f'<div class="notice">{link("gia-dat-nghia-trang-lac-hong-vien","Tìm hiểu thông tin chi phí")}<br>{link("lien-he","Trao đổi nhu cầu của gia đình")}</div></article></section>'+cta())
P['lien-he']=('Liên hệ tư vấn Lạc Hồng Viên | Hẹn khảo sát & hỏi báo giá','Liên hệ hotline 0971 999 470 để tư vấn khuôn viên mộ, hỏi báo giá theo lô và xác nhận lịch tham quan Lạc Hồng Viên.',head('KẾT NỐI TƯ VẤN','Chúng tôi lắng nghe.<br>Gia đình thêm an lòng.','Bắt đầu từ nhu cầu của bạn. Cùng chuẩn bị thông tin trước khi trao đổi hoặc hẹn chuyến khảo sát.')+'''<section class="wrap contact-grid"><div><p class="eyebrow">TRAO ĐỔI TRỰC TIẾP</p><a class="phone" href="tel:0971999470">0971 999 470 ↗</a><p>Hotline đang được công bố trên congviennghiatrang.com.</p><div class="contact-note"><h3>Hẹn tham quan</h3><p>Liên hệ trước để thống nhất ngày, điểm gặp và người hướng dẫn. Lịch chỉ có hiệu lực sau khi được xác nhận trực tiếp.</p></div><div class="contact-note"><h3>Yêu cầu báo giá</h3><p>Chuẩn bị loại khuôn viên, nhu cầu bố trí, ngân sách dự kiến và thời điểm cần sử dụng.</p></div>'''+link('vi-tri','Xem hướng dẫn chuyến đi')+'''</div><form id="request-form"><h2>Chuẩn bị nội dung trao đổi</h2><p>Điền lựa chọn để soạn lời nhắn. Bạn có thể sao chép và gửi qua kênh liên lạc đang dùng; biểu mẫu này không tự gửi hoặc lưu thông tin.</p><label for="need">Nhu cầu của gia đình</label><select id="need" name="need"><option>Tìm hiểu khuôn viên mộ</option><option>Nhận báo giá theo lô</option><option>Đặt lịch tham quan</option><option>Tìm hiểu dịch vụ chăm sóc</option></select><label for="type">Loại khuôn viên quan tâm</label><select id="type" name="type"><option>Chưa xác định, cần tư vấn</option><option>Mộ đơn</option><option>Mộ đôi</option><option>Khuôn viên gia đình</option></select><label for="note">Ghi chú thêm (không bắt buộc)</label><textarea id="note" rows="3" maxlength="1000" placeholder="Ví dụ: Gia đình muốn khảo sát vào cuối tuần…"></textarea><button class="button" type="submit">Soạn nội dung yêu cầu ↗</button><div id="request-result" hidden><h3>Nội dung đã soạn</h3><p id="request-text"></p><button class="chip" type="button" id="copy-request">Sao chép nội dung</button><p role="status" id="copy-status"></p><a href="tel:0971999470">Hoặc gọi 0971 999 470 để trao đổi</a></div></form></section>''')
P['chinh-sach-thong-tin']=('Chính sách thông tin & quyền riêng tư','Cách website Lạc Hồng Viên trình bày thông tin, sử dụng hình ảnh và xử lý biểu mẫu soạn yêu cầu tư vấn.',head('THÔNG TIN WEBSITE','Minh bạch trong từng thông tin.','Chính sách sử dụng nội dung và quyền riêng tư của bản website này.')+'''<article class="wrap policy"><h2>Vai trò của website</h2><p>congviennghiatrang.com là kênh thông tin và kết nối tư vấn về dự án Lạc Hồng Viên. Website không tự nhận là trang chính thức của chủ đầu tư. Nội dung không thay thế hồ sơ, hợp đồng và xác nhận của đơn vị có thẩm quyền.</p><h2>Giá và dịch vụ</h2><p>Giá từng lô, tình trạng cung cấp, điều kiện sử dụng và phạm vi dịch vụ phải được xác nhận tại thời điểm trao đổi. Website không đưa ra cam kết lợi nhuận, thời hạn sử dụng hoặc giá cố định khi chưa có hồ sơ xác nhận.</p><h2>Biểu mẫu và dữ liệu</h2><p>Biểu mẫu liên hệ chỉ tạo nội dung ngay trên thiết bị để người dùng xem và sao chép. Website này chưa kết nối hệ thống tiếp nhận yêu cầu, không tự gửi và không lưu nội dung biểu mẫu vào máy chủ. Tính năng sao chép chỉ ghi vào bộ nhớ tạm khi bạn bấm nút.</p><h2>Liên kết ngoài</h2><p>Google Maps và cuộc gọi điện thoại được mở theo lựa chọn của người dùng. Khi truy cập dịch vụ bên ngoài, chính sách của dịch vụ đó được áp dụng.</p><h2>Hình ảnh và nguồn</h2><p>Hình ảnh và hotline được đối chiếu từ website congviennghiatrang.com ngày 20/10/2026. Một số nhóm dịch vụ được tham khảo từ trang dịch vụ của lachongvien.vn. Ảnh phản ánh thời điểm ghi hình, không bảo đảm hiện trạng và quỹ lô hiện tại.</p><h2>Đề nghị chỉnh sửa</h2><p>Liên hệ <a href="tel:0971999470">0971 999 470</a> để phản ánh nội dung cần kiểm tra, cập nhật hoặc đính chính.</p></article>''')
for slug,(title,desc,body) in P.items():
 active='cam-nang' if slug in [a[0] for a in articles] else slug
 links=''.join(f'<a href="{url(s)}" '+('aria-current="page" ' if s==active else '')+f'>{t}</a>' for s,t in nav)
